import React, { useMemo } from 'react';
import { Box, Paper, Typography } from '@mui/material';
import {
  Assessment as AssessmentIcon,
  Description as DocumentsIcon,
  Factory as OperationsIcon,
  Flag as TargetsIcon,
  Forest as OffsetsIcon,
  Hub as ConnectorsIcon,
  Savings as SavingsIcon,
  Summarize as ReportingIcon,
  VerifiedUser as ComplianceIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';

type QuickAction = {
  label: string;
  path: string;
  icon: typeof AssessmentIcon;
};

/** Linear MSME core: Bills → Footprint → Report. */
const CORE_ACTIONS: QuickAction[] = [
  { label: 'Upload bills', path: '/document-upload', icon: DocumentsIcon },
  { label: 'Data connectors', path: '/data?section=connectors', icon: ConnectorsIcon },
  { label: 'Operations', path: '/operations', icon: OperationsIcon },
  { label: 'Carbon footprint', path: '/carbon-footprint?section=start-assessment', icon: AssessmentIcon },
  { label: 'Pick report goal', path: '/reporting?tab=0', icon: ReportingIcon },
];

const BASELINE_ACTIONS: QuickAction[] = [
  { label: 'Compliance hub', path: '/compliance', icon: ComplianceIcon },
  { label: 'Reduction targets', path: '/emissions-reduction-targets', icon: TargetsIcon },
  { label: 'Carbon savings', path: '/carbon-savings', icon: SavingsIcon },
  { label: 'Carbon offsets', path: '/carbon-marketplace?tab=0', icon: OffsetsIcon },
];

export interface DashboardQuickActionsProps {
  hasAssessment?: boolean;
  hasDocuments?: boolean;
  hasWorkflow?: boolean;
}

export const DashboardQuickActions: React.FC<DashboardQuickActionsProps> = ({
  hasAssessment = false,
}) => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  const actions = useMemo(() => {
    if (!hasAssessment) {
      return CORE_ACTIONS;
    }
    return [...CORE_ACTIONS, ...BASELINE_ACTIONS];
  }, [hasAssessment]);

  return (
    <Box>
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5 }}>
        Quick actions
      </Typography>
      <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
        {hasAssessment
          ? 'Bills, connectors, operations, footprint, and reporting — plus optimization tools below.'
          : 'Upload bills or connect accounting, map operations, then run your footprint and pick a report goal.'}
      </Typography>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: {
            xs: 'repeat(2, 1fr)',
            sm: 'repeat(3, 1fr)',
            md: `repeat(${Math.min(actions.length, 5)}, 1fr)`,
          },
          gap: 1.25,
        }}
      >
        {actions.map((action) => {
          const Icon = action.icon;
          return (
            <Paper
              key={action.path}
              component="button"
              type="button"
              onClick={() => navigate(action.path)}
              elevation={0}
              sx={{
                p: 1.5,
                textAlign: 'left',
                cursor: 'pointer',
                border: 1,
                borderColor: 'divider',
                borderRadius: 2,
                bgcolor: isDark ? alpha(theme.palette.common.white, 0.03) : 'background.paper',
                transition: 'border-color 0.15s ease, background-color 0.15s ease',
                '&:hover': {
                  borderColor: 'primary.main',
                  bgcolor: alpha(theme.palette.primary.main, isDark ? 0.12 : 0.04),
                },
              }}
            >
              <Icon color="primary" fontSize="small" sx={{ mb: 0.75, display: 'block' }} />
              <Typography variant="body2" sx={{ fontWeight: 600, lineHeight: 1.3 }}>
                {action.label}
              </Typography>
            </Paper>
          );
        })}
      </Box>
    </Box>
  );
};

export default DashboardQuickActions;
