export const MSME_REPORTING_INTENT_STORAGE_KEY = 'msme_reporting_intent_v1';

export function getStoredMsmeReportGoal(serverIntent?: string | null): string | null {
  const fromServer = typeof serverIntent === 'string' && serverIntent.trim() ? serverIntent.trim() : null;
  if (fromServer) {
    return fromServer;
  }
  if (typeof window === 'undefined') {
    return null;
  }
  try {
    const value = window.localStorage.getItem(MSME_REPORTING_INTENT_STORAGE_KEY);
    return value && value.trim() ? value.trim() : null;
  } catch {
    return null;
  }
}

export function setStoredMsmeReportGoal(intentId: string): void {
  if (typeof window === 'undefined') {
    return;
  }
  try {
    window.localStorage.setItem(MSME_REPORTING_INTENT_STORAGE_KEY, intentId);
  } catch {
    // ignore quota / private mode
  }
}

/** Persist report goal locally and on MSME profile (agentic journey continuity). */
export async function persistMsmeReportGoal(
  intentId: string,
  updateProfile?: (payload: { uxPreferences: { reportingIntent: string } }) => Promise<unknown>
): Promise<void> {
  setStoredMsmeReportGoal(intentId);
  if (!updateProfile) {
    return;
  }
  try {
    await updateProfile({ uxPreferences: { reportingIntent: intentId } });
  } catch {
    // Local storage remains the offline fallback
  }
}

